// @generated by:gauntlet run:g-o-d-s-e-y-e-owner-auth
import { expect, test } from "@playwright/test";
import {
  authenticateOwnerPasskey,
  browserOwnerRequest,
  type OwnerBrowserServer,
  overrideUserVerification,
  ownerBrowserServer,
  registerOwnerPasskey,
  virtualOwnerAuthenticator,
} from "./owner-fixture.js";

test.describe("isolated owner WebAuthn ceremonies", () => {
  let server: OwnerBrowserServer;

  test.beforeEach(async ({ page }) => {
    server = await ownerBrowserServer();
    await page.goto(server.origin);
  });
  test.afterEach(async () => {
    await server.close();
  });

  test("T-AC-01 enrolls a verified resident passkey and keeps session tokens out of JSON", async ({
    page,
  }) => {
    await virtualOwnerAuthenticator(page);
    const enrollment = await server.identity.prepareEnrollment("setup");
    const registration = await registerOwnerPasskey(page, enrollment.ticket);
    expect(registration.status).toBe(200);
    expect(registration.body.session).not.toHaveProperty("token");
    const status = await browserOwnerRequest(page, "/api/v1/owner/session");
    expect(status.body).toMatchObject({
      authenticated: true,
      configured: true,
      owner: { id: server.identity.ownerId },
    });
    expect(status.body.session).not.toHaveProperty("token");
    expect((await browserOwnerRequest(page, "/api/v1/projects")).status).toBe(200);
    const cookies = await page.context().cookies();
    const sessionCookie = cookies.find((cookie) => cookie.name.endsWith("session_token"));
    expect(sessionCookie?.httpOnly).toBe(true);
    expect(["Lax", "Strict"]).toContain(sessionCookie?.sameSite);
  });

  test("T-AC-01 signs out and signs back in using a required-UV passkey ceremony", async ({
    page,
  }) => {
    await virtualOwnerAuthenticator(page);
    const enrollment = await server.identity.prepareEnrollment("setup");
    expect((await registerOwnerPasskey(page, enrollment.ticket)).status).toBe(200);
    expect((await browserOwnerRequest(page, "/api/auth/sign-out", "POST")).status).toBe(200);
    expect((await browserOwnerRequest(page, "/api/v1/projects")).status).toBe(401);
    const signIn = await authenticateOwnerPasskey(page);
    expect(signIn.status).toBe(200);
    expect(signIn.userVerification).toBe("required");
    expect(signIn.body.session).not.toHaveProperty("token");
    expect((await browserOwnerRequest(page, "/api/v1/projects")).status).toBe(200);
  });

  test("T-AC-01 refuses reusing a consumed setup ticket after sign-out", async ({ page }) => {
    await virtualOwnerAuthenticator(page);
    const enrollment = await server.identity.prepareEnrollment("setup");
    expect((await registerOwnerPasskey(page, enrollment.ticket)).status).toBe(200);
    await browserOwnerRequest(page, "/api/auth/sign-out", "POST");
    const replay = await registerOwnerPasskey(page, enrollment.ticket);
    expect(replay.status).toBeGreaterThanOrEqual(400);
    expect(replay.status).toBeLessThan(500);
    expect((await browserOwnerRequest(page, "/api/v1/projects")).status).toBe(401);
    await expect(server.identity.prepareEnrollment("setup")).rejects.toThrow();
  });

  test("T-AC-01 refuses HTTP revocation of the owner's final passkey", async ({ page }) => {
    await virtualOwnerAuthenticator(page);
    const enrollment = await server.identity.prepareEnrollment("setup");
    expect((await registerOwnerPasskey(page, enrollment.ticket)).status).toBe(200);
    const security = await browserOwnerRequest(page, "/api/v1/owner/security");
    const passkey = security.body.passkeys[0] as { id: string } | undefined;
    if (!passkey) throw new Error("Missing enrolled browser passkey");
    const response = await page.evaluate(async (id) => {
      const response = await fetch(`/api/v1/owner/passkeys/${id}/revoke`, {
        method: "POST",
        headers: { "content-type": "application/json", "idempotency-key": crypto.randomUUID() },
        body: "{}",
      });
      return { status: response.status, body: await response.json() };
    }, passkey.id);
    expect(response.status).toBe(409);
    expect(response.body.error.code).toBe("LAST_PASSKEY");
    const unchanged = await browserOwnerRequest(page, "/api/v1/owner/security");
    expect(unchanged.body.passkeys).toHaveLength(1);
  });

  test("T-AC-01 rejects passkey authentication when user verification is absent", async ({
    page,
  }) => {
    const authenticator = await virtualOwnerAuthenticator(page);
    const enrollment = await server.identity.prepareEnrollment("setup");
    expect((await registerOwnerPasskey(page, enrollment.ticket)).status).toBe(200);
    await browserOwnerRequest(page, "/api/auth/sign-out", "POST");
    await overrideUserVerification(authenticator, true);
    const rejected = await authenticateOwnerPasskey(page);
    expect(rejected.status).toBeGreaterThanOrEqual(400);
    expect(rejected.status).toBeLessThan(500);
    expect((await browserOwnerRequest(page, "/api/v1/projects")).status).toBe(401);
    await overrideUserVerification(authenticator, false);
    expect((await authenticateOwnerPasskey(page)).status).toBe(200);
  });

  test("T-AC-01 rejects an unverified authenticator response without consuming enrollment", async ({
    page,
  }) => {
    const authenticator = await virtualOwnerAuthenticator(page);
    const enrollment = await server.identity.prepareEnrollment("setup");
    await overrideUserVerification(authenticator, true);
    const rejected = await registerOwnerPasskey(page, enrollment.ticket);
    expect(rejected.status).toBeGreaterThanOrEqual(400);
    expect((await browserOwnerRequest(page, "/api/v1/owner/session")).body).toMatchObject({
      authenticated: false,
      configured: false,
    });
    await overrideUserVerification(authenticator, false);
    expect((await registerOwnerPasskey(page, enrollment.ticket)).status).toBe(200);
  });

  test("T-AC-01 rejects a changed WebAuthn origin without consuming enrollment", async ({
    page,
  }) => {
    await virtualOwnerAuthenticator(page);
    const enrollment = await server.identity.prepareEnrollment("setup");
    const rejected = await registerOwnerPasskey(page, enrollment.ticket, "http://attacker.invalid");
    expect(rejected.status).toBeGreaterThanOrEqual(400);
    expect((await browserOwnerRequest(page, "/api/v1/owner/session")).body).toMatchObject({
      authenticated: false,
      configured: false,
    });
    expect((await registerOwnerPasskey(page, enrollment.ticket)).status).toBe(200);
  });

  test("T-AC-01 recovery revokes the old session and passkey before enrolling a replacement", async ({
    page,
  }) => {
    await virtualOwnerAuthenticator(page);
    const enrollment = await server.identity.prepareEnrollment("setup");
    expect((await registerOwnerPasskey(page, enrollment.ticket)).status).toBe(200);
    const recovery = await server.identity.prepareEnrollment("recover");
    expect((await browserOwnerRequest(page, "/api/v1/projects")).status).toBe(401);
    const oldPasskey = await authenticateOwnerPasskey(page);
    expect(oldPasskey.status).toBeGreaterThanOrEqual(400);
    expect(oldPasskey.status).toBeLessThan(500);
    expect((await registerOwnerPasskey(page, recovery.ticket)).status).toBe(200);
    expect((await browserOwnerRequest(page, "/api/v1/projects")).status).toBe(200);
  });

  test("T-AC-01 permits only one successful enrollment when two ceremonies share a ticket", async ({
    page,
    browser,
  }) => {
    await virtualOwnerAuthenticator(page);
    const otherContext = await browser.newContext();
    try {
      const otherPage = await otherContext.newPage();
      await otherPage.goto(server.origin);
      await virtualOwnerAuthenticator(otherPage);
      const enrollment = await server.identity.prepareEnrollment("setup");
      const attempts = await Promise.all([
        registerOwnerPasskey(page, enrollment.ticket),
        registerOwnerPasskey(otherPage, enrollment.ticket),
      ]);
      expect(attempts.filter((attempt) => attempt.status === 200)).toHaveLength(1);
      expect(
        attempts.filter((attempt) => attempt.status >= 400 && attempt.status < 500),
      ).toHaveLength(1);
      const context = await server.identity.auth.$context;
      const passkeys = await context.adapter.findMany({
        model: "passkey",
        where: [{ field: "userId", value: server.identity.ownerId }],
      });
      expect(passkeys).toHaveLength(1);
    } finally {
      await otherContext.close();
    }
  });
});
